<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_login();
$user=current_user();$pdo=db();
if(!$user||!$pdo){flash('error','Account unavailable.');redirect(url('/login.php'));}
if(!subscription_schema_ready($pdo))redirect(url('/upgrade.php'));

$subscription=subscription_current($user);$balance=subscription_ai_balance($user,$pdo);$usage=subscription_usage_by_scope((int)$user['id'],30);$credits=subscription_recent_credits((int)$user['id'],30);$packages=subscription_packages(true);
$allowance=max(0,(int)($balance['package_allowance']??0));$remaining=(int)($balance['remaining']??0);$used=(int)($balance['used']??0);
$percent=$allowance>0?min(100,(int)round(($used/$allowance)*100)):0;
$warning='';
if(empty($balance['unlimited'])){
    if($remaining<=0)$warning='Your AI token balance is exhausted. Non-AI features remain available; an Admin can add tokens or assign another package.';
    elseif($percent>=95)$warning='You have used at least 95% of your package AI allowance.';
    elseif($percent>=80)$warning='You have used at least 80% of your package AI allowance.';
    elseif($percent>=50)$warning='You have used at least 50% of your package AI allowance.';
}
$entitlements=[];
if($subscription){$pkg=subscription_package((int)$subscription['package_id']);foreach(($pkg['entitlements']??[]) as $row)$entitlements[(string)$row['capability_key']]=$row;}
$periodEnd=(string)($subscription['current_period_end']??$subscription['ends_at']??'');
?>
