<section class="plan-card" style="margin-top:14px"><h2>Included Features</h2><p class="plan-muted">Your package is the commercial account type. Team roles are separate workspace relationships.</p><div class="plan-feature-grid"><?php foreach(subscription_capability_catalog() as $key=>$meta):if(str_starts_with($key,'permission.')||in_array($key,['legacy.permissions','ai.unlimited'],true))continue;$row=$entitlements[$key]??null;$enabled=$row&&(int)$row['is_enabled']===1;?><div class="plan-feature"><small><?= e((string)($meta['category']??'Feature')) ?></small><b><?= e((string)$meta['label']) ?></b><span><?= $enabled?(($meta['type']??'boolean')==='limit'&&$row['limit_value']!==null?number_format((int)$row['limit_value']).' included':'Included'):'Not included' ?></span></div><?php endforeach;?></div></section>
<section class="plan-card" style="margin-top:14px"><h2>AI Usage by Feature</h2><div style="overflow:auto"><table class="plan-table"><thead><tr><th>Feature</th><th>Requests</th><th>Input</th><th>Output</th><th>Total</th></tr></thead><tbody><?php foreach($usage as $row):?><tr><td><?= e((string)$row['scope']) ?></td><td><?= number_format((int)$row['requests']) ?></td><td><?= number_format((int)$row['input_tokens']) ?></td><td><?= number_format((int)$row['output_tokens']) ?></td><td><?= number_format((int)$row['total_tokens']) ?></td></tr><?php endforeach;?><?php if(!$usage):?><tr><td colspan="5">No metered AI usage yet.</td></tr><?php endif;?></tbody></table></div></section>
